<?php
declare(strict_types=1);
if(session_status()===PHP_SESSION_NONE)session_start();
foreach([__DIR__.'/../includes/auth.php',__DIR__.'/../includes/auth_helpers.php',__DIR__.'/../auth.php'] as $f){if(is_file($f)){require_once $f;break;}}
foreach([__DIR__.'/../includes/conn.php',__DIR__.'/../config.php',__DIR__.'/../db.php'] as $f){if(is_file($f)){require_once $f;if(isset($conn)&&$conn instanceof mysqli)break;}}
if(function_exists('require_login'))require_login();if((string)($_SESSION['role']??'')!=='Admin'){http_response_code(403);exit('Access denied.');}if(!isset($conn)||!($conn instanceof mysqli))exit('Database connection unavailable.');$pharmacyId=(int)($_SESSION['pharmacy_id']??0);if(empty($_SESSION['zra_csrf']))$_SESSION['zra_csrf']=bin2hex(random_bytes(24));
$branches=[];$s=$conn->prepare('SELECT id,branch_name FROM branches WHERE pharmacy_id=? ORDER BY branch_name');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$branches[]=$x;$s->close();}
$items=[];$sql="SELECT id,item_name,barcode,price,tax_rate,branch_id,zra_item_cd,zra_item_cls_cd,zra_registered FROM store_items WHERE pharmacy_id=? ORDER BY id DESC LIMIT 100";$s=$conn->prepare($sql);if($s){$s->bind_param('i',$pharmacyId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$items[]=$x;$s->close();}
