?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZRA Item Registration</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>body{margin:0;background:#f4f6f9;color:#17202b;font:14px Inter,system-ui,sans-serif}.main{min-height:100vh}.wrap{padding:24px;max-width:1600px;margin:auto}.panel{background:#fff;border:1px solid #e3e8ef;border-radius:12px;margin-bottom:16px;overflow:hidden;box-shadow:0 4px 18px rgba(15,23,42,.06)}.ph{padding:16px 18px;border-bottom:1px solid #e3e8ef}.pb{padding:18px}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.field input,.field select{width:100%;padding:10px;border:1px solid #d9e0e8;border-radius:8px;box-sizing:border-box}.btn{padding:10px 14px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:800;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #edf0f4;text-align:left;font-size:12px}th{font-size:10px;color:#667789;text-transform:uppercase;background:#fafbfc}@media(max-width:900px){.fields{grid-template-columns:1fr}.wrap{padding:14px}}</style></head><body><div class="app"><?php if(is_file($aside))require $aside;?><main class="main"><?php if(is_file($header))require $header;?><div class="wrap"><div class="panel"><div class="ph"><h1 style="margin:0">ZRA Item Registration</h1><p style="color:#718096">Register/classify EchoTech POS products before they can be submitted on sales.</p></div><div class="pb"><form method="post" action="actions/zra_items.php"><input type="hidden" name="csrf" value="<?=ze($_SESSION['zra_csrf'])?>"><div class="fields"><div class="field"><label>Product</label><select name="product_id" required><?php foreach($items as $i):?><option value="<?=$i['id']?>"><?=ze($i['item_name'])?> — K<?=number_format((float)$i['price'],2)?></option><?php endforeach;?></select></div><div class="field"><label>Branch</label><select name="branch_id" required><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=ze($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label>ZRA bhfId</label><input name="bhf_id" maxlength="3" placeholder="000" required></div><div class="field"><label>ZRA Item Code</label><input name="item_cd" required placeholder="Enter ZRA-approved item code"></div><div class="field"><label>UNSPSC Classification Code</label><input name="item_cls_cd" required placeholder="Level 4 commodity code"></div><div class="field"><label>Item Type</label><select name="item_ty_cd"><option value="2">2 — Finished product</option><option value="1">1 — Raw material</option><option value="3">3 — Service</option></select></div><div class="field"><label>Origin Country</label><input name="orgn_nat_cd" value="ZM" maxlength="5"></div><div class="field"><label>Packaging Unit</label><input name="pkg_unit_cd" value="EA" maxlength="5"></div><div class="field"><label>Quantity Unit</label><input name="qty_unit_cd" value="EA" maxlength="5"></div><div class="field"><label>Tax Type</label><input name="tax_ty_cd" value="A" maxlength="5"></div></div><button class="btn"><i class="fa-solid fa-cloud-arrow-up"></i> Register Item with ZRA</button></form></div></div><div class="panel"><div class="ph"><h2 style="margin:0">Product ZRA status</h2></div><div class="pb" style="overflow:auto"><table><thead><tr><th>Product</th><th>Branch</th><th>ZRA Item</th><th>Class</th><th>Tax</th><th>Status</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=ze($i['item_name'])?></td><td><?=ze($i['branch_id'])?></td><td><?=ze($i['zra_item_cd']??'-')?></td><td><?=ze($i['zra_item_cls_cd']??'-')?></td><td><?=ze($i['tax_rate'])?>%</td><td><?=((int)($i['zra_registered']??0)===1)?'<b style="color:#059669">Registered</b>':'<b style="color:#d97706">Pending</b>'?></td></tr><?php endforeach;?></tbody></table></div></div></div></main></div></body></html>
